import React, { useState, useRef } from 'react';
import { useNavigate, Link, useLocation } from 'react-router-dom';
import { useDispatch } from 'react-redux';
import { loginStart, loginSuccess, loginFailure } from '../../store/authSlice';
import { enrollStudentAsync } from '../../store/contentSlice';
import { startCourse } from '../../store/activitySlice';
import { supabaseService } from '../../services/supabaseService';
import Button from '../../components/ui/Button';
import Input from '../../components/ui/Input';
import Icon from '../../components/AppIcon';
import { Turnstile } from '@marsidev/react-turnstile';

const Signup = () => {
  const [step, setStep] = useState(1);
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [confirm, setConfirm] = useState('');
  const [gender, setGender] = useState('');
  const [phone, setPhone] = useState('');
  const [ageRange, setAgeRange] = useState('');
  const [demography, setDemography] = useState('');
  const [country, setCountry] = useState('');
  const [captchaToken, setCaptchaToken] = useState(null);
  const [error, setError] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [signupSuccess, setSignupSuccess] = useState(false);
  const turnstileRef = useRef(null);
  const [resendStatus, setResendStatus] = useState('');
  const navigate = useNavigate();
  const location = useLocation();
  const dispatch = useDispatch();

  const handleNextStep = () => {
    setError('');
    if (step === 1) {
      if (!name || !email) return setError('Name and Email are required');
      const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      if (!emailRegex.test(email)) return setError('Please enter a valid email address');
      setStep(2);
    } else if (step === 2) {
      if (!gender || !phone || !ageRange || !demography || !country) {
        return setError('Please fill in all demographic fields to continue');
      }
      setStep(3);
    }
  };

  const handlePrevStep = () => {
    setError('');
    setStep(prev => Math.max(1, prev - 1));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    
    if (step !== 3) return;
    
    if (!password || !confirm) return setError('Password is required');
    if (password.length < 6) return setError('Password must be at least 6 characters');
    if (password !== confirm) return setError('Passwords do not match');

    if (!captchaToken) {
        setError('Please complete the security check');
        return;
    }

    setIsSubmitting(true);
    dispatch(loginStart());
    try {
      const params = new URLSearchParams(window.location.search);
      const referralCode = params.get('ref');
      const extraData = { 
          gender: gender,
          phone: phone, 
          age_range: ageRange, 
          demography: demography, 
          country: country 
      };
      const res = await supabaseService.signup(email, password, name, captchaToken, referralCode, extraData);

      if (res.user) {
        // Check if user is already session-active (confirms email is OFF)
        if (res.session) {
          dispatch(loginSuccess({
            token: res.session.access_token,
            user: res.user,
            role: 'user'
          }));

          // Add new user to General Community chat immediately
          try {
            const generalId = '00000000-0000-0000-0000-000000000000';
            await supabaseService.supabase
                .from('chat_channel_members')
                .upsert({ channel_id: generalId, user_id: res.user.id }, { onConflict: 'channel_id,user_id' });
          } catch (chatErr) {
            console.warn('Failed to join general chat on signup:', chatErr);
          }

          // Consume pending intake from guest enrollment flow
          const pendingIntake = JSON.parse(sessionStorage.getItem('pendingIntake') || 'null');
          if (pendingIntake) {
            try {
              if (pendingIntake.isTrack && pendingIntake.trackCourses?.length > 0) {
                await supabaseService.enrollInTrack(
                  res.user.id,
                  String(pendingIntake.courseId),
                  pendingIntake.trackCourses.map(String),
                  0
                );
                pendingIntake.trackCourses.forEach(cId => {
                  dispatch(enrollStudentAsync({ courseId: cId, type: 'academy' }));
                  dispatch(startCourse({ courseId: cId }));
                });
              } else if (pendingIntake.courseId) {
                dispatch(enrollStudentAsync({ courseId: pendingIntake.courseId, type: 'academy' }));
                dispatch(startCourse({ courseId: pendingIntake.courseId }));
              }
            } catch (enrollErr) {
              console.warn('Auto-enrollment after signup failed:', enrollErr);
            }
            sessionStorage.removeItem('pendingIntake');
          }

          const params = new URLSearchParams(window.location.search);
          const redirectParam = params.get('redirect');
          const from = redirectParam || location.state?.from || '/';
          navigate(from);
        } else {
          // Confirmation is ON
          setSignupSuccess(true);
        }
      } else {
        setError('Signup failed. Please try again.');
        dispatch(loginFailure('Signup failed'));
      }
    } catch (err) {
      setError(err.message || 'Signup failed');
      dispatch(loginFailure(err.message || 'Signup failed'));
      // Reset captcha on failure to prevent "timeout-or-duplicate" errors
      if (turnstileRef.current) {
          turnstileRef.current.reset();
          setCaptchaToken(null);
      }
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleResend = async () => {
    setResendStatus('sending');
    try {
      await supabaseService.resendConfirmationEmail(email);
      setResendStatus('sent');
      setTimeout(() => setResendStatus(''), 5000);
    } catch (err) {
      setResendStatus('error');
      setError(err.message || 'Failed to resend email');
    }
  };

  if (signupSuccess) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-primary via-secondary to-accent flex items-center justify-center p-4">
        <div className="w-full max-w-md">
          <div className="bg-white dark:bg-gray-900 rounded-[2.5rem] shadow-2xl p-10 text-center border border-gray-100 dark:border-white/10 relative overflow-hidden">
            <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-primary to-secondary opacity-50" />

            <div className="w-24 h-24 bg-primary/10 dark:bg-primary/5 rounded-[2rem] flex items-center justify-center text-primary mx-auto mb-8 shadow-sm border border-primary/10">
              <Icon name="MailCheck" size={48} />
            </div>

            <h2 className="text-3xl font-bold text-gray-900 dark:text-white mb-4">Confirm your email</h2>
            <p className="text-gray-600 dark:text-gray-400 mb-8 leading-relaxed max-w-xs mx-auto text-sm">
              We've sent a verification link to <span className="font-bold text-primary dark:text-white">{email}</span>.
              Please check your inbox to activate your account.
            </p>

            <div className="space-y-4">
              <Button
                onClick={handleResend}
                disabled={resendStatus === 'sending'}
                fullWidth
                size="xl"
                loading={resendStatus === 'sending'}
                variant={resendStatus === 'sent' ? 'success' : 'default'}
                iconName={resendStatus === 'sent' ? 'CheckCircle' : 'Send'}
              >
                {resendStatus === 'sent' ? 'Email Sent!' : 'Resend Verification Email'}
              </Button>

              <div className="pt-4 mt-4 border-t border-gray-100 dark:border-white/5">
                <p className="text-xs text-gray-500">
                  Entered the wrong email? {' '}
                  <button onClick={() => setSignupSuccess(false)} className="text-primary font-bold hover:underline">
                    Back to signup
                  </button>
                </p>
              </div>
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-primary via-secondary to-accent flex items-center justify-center p-4">
      <div className="w-full max-w-md">
        <div className="bg-white dark:bg-gray-800 rounded-lg shadow-2xl p-8">
          <div className="flex items-center justify-between mb-6">
            <h2 className="text-2xl font-bold">
              {step === 1 && "Create an account"}
              {step === 2 && "Ecosystem Profile"}
              {step === 3 && "Secure Account"}
            </h2>
            <div className="flex gap-1">
              {[1, 2, 3].map(s => (
                <div key={s} className={`h-1.5 w-6 rounded-full transition-colors duration-500 ${step >= s ? 'bg-primary' : 'bg-gray-200 dark:bg-gray-700'}`} />
              ))}
            </div>
          </div>

          <p className="text-sm text-gray-500 mb-6">
            {step === 1 && "Step 1 of 3: Enter your basic details"}
            {step === 2 && "Step 2 of 3: Tell us about yourself"}
            {step === 3 && "Step 3 of 3: Set your password"}
          </p>

          <div className="mb-4">
            {step === 1 ? (
              <Button asChild variant="ghost" size="sm" className="px-2 py-1">
                <Link to="/">← Back to Home</Link>
              </Button>
            ) : (
              <Button type="button" onClick={handlePrevStep} variant="ghost" size="sm" className="px-2 py-1">
                ← Back
              </Button>
            )}
          </div>

          {error && <div className="mb-4 text-sm text-red-700 font-medium p-3 bg-red-50 rounded-md border border-red-100">{error}</div>}

          <form onSubmit={step === 3 ? handleSubmit : (e) => { e.preventDefault(); handleNextStep(); }} className="space-y-4">
            
            {step === 1 && (
              <div className="space-y-4 animate-in fade-in slide-in-from-right-4 duration-300">
                <div>
                  <label className="block text-sm font-semibold mb-2">Full name</label>
                  <Input placeholder="John Doe" value={name} onChange={(e) => setName(e.target.value)} />
                </div>
                <div>
                  <label className="block text-sm font-semibold mb-2">Email</label>
                  <Input placeholder="john@example.com" value={email} onChange={(e) => setEmail(e.target.value)} type="email" />
                </div>
              </div>
            )}

            {step === 2 && (
              <div className="space-y-4 animate-in fade-in slide-in-from-right-4 duration-300">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-semibold mb-2">Gender</label>
                    <select 
                      value={gender} 
                      onChange={(e) => setGender(e.target.value)}
                      className="w-full flex h-10 rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50"
                    >
                      <option value="" disabled>Select Gender</option>
                      <option value="Male">Male</option>
                      <option value="Female">Female</option>
                      <option value="Non-binary">Non-binary</option>
                      <option value="Prefer not to say">Prefer not to say</option>
                    </select>
                  </div>
                  <div>
                    <label className="block text-sm font-semibold mb-2">Age Range</label>
                    <select 
                      value={ageRange} 
                      onChange={(e) => setAgeRange(e.target.value)}
                      className="w-full flex h-10 rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50"
                    >
                      <option value="" disabled>Select Age Range</option>
                      <option value="Under 18">Under 18</option>
                      <option value="18-24">18-24</option>
                      <option value="25-34">25-34</option>
                      <option value="35-44">35-44</option>
                      <option value="45-54">45-54</option>
                      <option value="55+">55+</option>
                    </select>
                  </div>
                </div>

                <div>
                  <label className="block text-sm font-semibold mb-2">Phone Number</label>
                  <Input placeholder="+1 234 567 8900" value={phone} onChange={(e) => setPhone(e.target.value)} type="tel" />
                </div>
                <div>
                  <label className="block text-sm font-semibold mb-2">Demography / Occupation</label>
                  <Input placeholder="e.g. Student, Founder, Professional" value={demography} onChange={(e) => setDemography(e.target.value)} />
                </div>
                <div>
                  <label className="block text-sm font-semibold mb-2">Country of Residence</label>
                  <Input placeholder="e.g. United States, Nigeria, UK" value={country} onChange={(e) => setCountry(e.target.value)} />
                </div>
              </div>
            )}

            {step === 3 && (
              <div className="space-y-4 animate-in fade-in slide-in-from-right-4 duration-300">
                <div>
                  <label className="block text-sm font-semibold mb-2">Password</label>
                  <Input placeholder="••••••••" value={password} onChange={(e) => setPassword(e.target.value)} type="password" />
                </div>
                <div>
                  <label className="block text-sm font-semibold mb-2">Confirm password</label>
                  <Input placeholder="••••••••" value={confirm} onChange={(e) => setConfirm(e.target.value)} type="password" />
                </div>

                <div className="flex justify-center my-4 overflow-hidden rounded-xl border border-gray-100 dark:border-gray-700 p-2 bg-gray-50 dark:bg-gray-900/50">
                  <Turnstile 
                    ref={turnstileRef}
                    siteKey={import.meta.env.VITE_TURNSTILE_SITE_KEY} 
                    onSuccess={(token) => setCaptchaToken(token)}
                    onError={() => setError('Security check failed. Please refresh.')}
                    theme="auto"
                  />
                </div>
              </div>
            )}

            <Button type="submit" disabled={isSubmitting} className="w-full mt-6">
              {step < 3 ? 'Continue' : (isSubmitting ? 'Creating account...' : 'Create account')}
            </Button>
          </form>

          {step === 1 && (
            <div className="mt-6 text-sm text-center">
              <p>Already have an account? <Link className="text-primary font-semibold hover:underline" to={`/login${location.search}`}>Sign in</Link></p>
            </div>
          )}
          </div>
        </div>
      </div>
    );
};

export default Signup;
